// Proposition 7.5. Cyclic case of semistability defect 4.
// The Galois group is generated by x. Frobenius A is linear and t is trivial.
// The two signs of X occur for each nonzero supersingular trace.
Q := Rationals();
R<alpha,beta> := FunctionField(Q,2);

// Normal forms for a2=2.
A := Matrix(R,2,2,[0,-2,1,2]);
X := Matrix(R,2,2,[1,2,-1,-1]);
Xminus := Matrix(R,2,2,[-1,-2,1,1]);
T := Matrix(R,2,2,[1,0,0,1]);
assert X eq T-A and Xminus eq -X;
assert X^2 eq -T and Trace(X) eq 0 and Determinant(X) eq 1;
print "Normal form: A, X, Xminus, T", A, X, Xminus, T;

// To send (alpha,1) to (beta,1) with alpha!=beta use Bfil=c*I+A.
vAlpha := Matrix(R,2,1,[alpha,1]);
vBeta := Matrix(R,2,1,[beta,1]);
xAlpha := (alpha+2)/(-alpha-1);
xBeta := (beta+2)/(-beta-1);
xLine := Matrix(R,2,1,[xAlpha,1]);
assert X*xLine eq (-xAlpha-1)*vAlpha and Xminus*xLine eq (xAlpha+1)*vAlpha;
assert (xAlpha+2)/(-xAlpha-1) eq alpha;
c := (alpha*beta+2*beta+2)/(alpha-beta);
assert (xAlpha*xBeta+2*xBeta+2)/(xAlpha-xBeta) eq c;
Bfil := Matrix(R,2,2,[c,-2,1,c+2]);
assert Bfil*A eq A*Bfil and Bfil*X eq X*Bfil and Bfil*Xminus eq Xminus*Bfil;
assert Bfil*vAlpha eq (alpha+c+2)*vBeta;
assert Determinant(Bfil) eq (c+1)^2+1;
print "a2=2: filtration intertwiner", Bfil;

// Normal forms for a2=-2.
A := Matrix(R,2,2,[0,-2,1,-2]);
X := Matrix(R,2,2,[1,-2,1,-1]);
Xminus := Matrix(R,2,2,[-1,2,-1,1]);
T := Matrix(R,2,2,[1,0,0,1]);
assert X eq T+A and Xminus eq -X;
assert X^2 eq -T and Trace(X) eq 0 and Determinant(X) eq 1;
print "Normal form: A, X, Xminus, T", A, X, Xminus, T;

xAlpha := (alpha-2)/(alpha-1);
xBeta := (beta-2)/(beta-1);
xLine := Matrix(R,2,1,[xAlpha,1]);
assert X*xLine eq (xAlpha-1)*vAlpha and Xminus*xLine eq (1-xAlpha)*vAlpha;
assert (xAlpha-2)/(xAlpha-1) eq alpha;
c := (alpha*beta-2*beta+2)/(alpha-beta);
assert (xAlpha*xBeta-2*xBeta+2)/(xAlpha-xBeta) eq c;
Bfil := Matrix(R,2,2,[c,-2,1,c-2]);
assert Bfil*A eq A*Bfil and Bfil*X eq X*Bfil and Bfil*Xminus eq Xminus*Bfil;
assert Bfil*vAlpha eq (alpha+c-2)*vBeta;
assert Determinant(Bfil) eq (c-1)^2+1;
print "a2=-2: filtration intertwiner", Bfil;
// Each computation gives x(c)=c, hence c in Q_2. A square plus 1 is
// nonzero in Q_2. For alpha=beta, use the identity in either case.
// An A-intertwiner commutes with X, a polynomial in A. Intertwining X
// with -X would therefore force the intertwiner to be zero.

// Exhaustion of the normal forms. A commutes only with matrices c*I+d*A.
// Trace zero forces c=-a*d/2, leaving the matrix Xc below.
E<a,d> := PolynomialRing(Q,2);
Ac := Matrix(E,2,2,[0,-2,1,a]);
Xc := Matrix(E,2,2,[-a*d/2,-2*d,d,a*d/2]);
assert Ac*Xc eq Xc*Ac and Trace(Xc) eq 0;
assert 4*Determinant(Xc) eq (8-a^2)*d^2;
// For a=0, determinant one requires 2*d^2=1, impossible by valuation.
// For a=2 or -2 it requires d=1 or -1, giving the two displayed signs.

// The representative alpha=sqrt(2) satisfies the slope equation for both traces.
P<z> := PolynomialRing(Q);
K<s> := NumberField(z^2-2);
x := hom<K -> K | -s>;
assert x(s) eq (s+2)/(-s-1) and x(s) eq (s-2)/(s-1);

// Identify this quadratic subfield in each cyclic quartic of Table 2.
L1<s1> := NumberField(z^4-4*z^2+2);
L2<s2> := NumberField(z^4+4*z^2+2);
assert (s1^2-2)^2 eq 2 and (s2^2+2)^2 eq 2;

print "Proposition 7.5 verified.";
